package com.snaptvnow.smspuente;
import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import org.json.*;
final class MessageStore extends SQLiteOpenHelper {
 MessageStore(Context c){super(c,"sms_bridge.db",null,2);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE events(id TEXT PRIMARY KEY,raw TEXT NOT NULL,received INTEGER NOT NULL,day TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,last_attempt INTEGER NOT NULL DEFAULT 0,delivered INTEGER NOT NULL DEFAULT 0)");}
 public void onUpgrade(SQLiteDatabase db,int a,int b){if(a<2){db.execSQL("ALTER TABLE events ADD error TEXT NOT NULL DEFAULT ''");db.execSQL("ALTER TABLE events ADD attempts INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE events ADD last_attempt INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE events ADD delivered INTEGER NOT NULL DEFAULT 0");}}
 void scan(Context context,Vault v)throws Exception{
  long cursor=v.p.getLong("cursor",0),since=v.p.getLong("since",System.currentTimeMillis());int count=0;
  try(Cursor rows=context.getContentResolver().query(Uri.parse("content://sms/inbox"),new String[]{"_id","address","body","date"},"address=? AND _id>? AND date>=?",new String[]{"520",Long.toString(cursor),Long.toString(since)},"_id ASC")){
   if(rows==null)throw new Exception("No se pudo leer la bandeja SMS");while(rows.moveToNext()&&count++<200){long id=rows.getLong(0),time=rows.getLong(3);String source=rows.getString(1),body=rows.getString(2);if("520".equals(source)&&body!=null&&body.trim().matches("(?is)^BofA:.*sent you \\$.*")){ContentValues values=new ContentValues();values.put("id","sms:"+id);values.put("raw",body);values.put("received",time);values.put("day",Vault.day(time));values.put("status",body.length()>2000?"review":"pending");if(body.length()>2000)values.put("error","El SMS supera 2000 caracteres. Revisa el mensaje original.");getWritableDatabase().insertWithOnConflict("events",null,values,SQLiteDatabase.CONFLICT_IGNORE);}cursor=id;if(!v.p.edit().putLong("cursor",cursor).commit())throw new Exception("No se guardó el punto de lectura");}
  }
 }
 JSONObject first()throws Exception{try(Cursor r=getReadableDatabase().rawQuery("SELECT id,raw,received,day FROM events WHERE status='pending' ORDER BY received,id LIMIT 1",null)){if(!r.moveToFirst())return null;return new JSONObject().put("action","receive").put("source","520").put("messageId",r.getString(0)).put("sms",r.getString(1)).put("receivedAt",r.getLong(2)).put("paymentDate",r.getString(3));}}
 void attempt(String id){getWritableDatabase().execSQL("UPDATE events SET attempts=attempts+1,last_attempt=? WHERE id=? AND status='pending'",new Object[]{System.currentTimeMillis(),id});}
 void failed(String id,String reason,boolean review){ContentValues values=new ContentValues();values.put("status",review?"review":"pending");values.put("error",reason==null?"Entrega no confirmada":reason);getWritableDatabase().update("events",values,"id=? AND status!='sent'",new String[]{id});}
 void retry(String id){ContentValues values=new ContentValues();values.put("status","pending");values.put("error","");getWritableDatabase().update("events",values,"id=? AND status!='sent'",new String[]{id});}
 void sent(String id){ContentValues values=new ContentValues();values.put("status","sent");values.put("error","");values.put("delivered",System.currentTimeMillis());getWritableDatabase().update("events",values,"id=?",new String[]{id});}
 JSONObject stats()throws JSONException{try(Cursor r=getReadableDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(status='pending'),0),COALESCE(SUM(status='review'),0),COALESCE(MAX(received),0),COALESCE(MAX(delivered),0) FROM events",null)){r.moveToFirst();return new JSONObject().put("detected",r.getInt(0)).put("pending",r.getInt(1)).put("review",r.getInt(2)).put("lastDetectedAt",r.getLong(3)).put("lastDeliveredAt",r.getLong(4));}}
 JSONArray history(int offset)throws JSONException{JSONArray rows=new JSONArray();try(Cursor r=getReadableDatabase().rawQuery("SELECT id,raw,received,status,error,attempts,last_attempt,delivered FROM events ORDER BY CASE WHEN status='review' THEN 0 WHEN status='pending' THEN 1 ELSE 2 END,received DESC,id LIMIT 50 OFFSET ?",new String[]{Integer.toString(offset)})){while(r.moveToNext())rows.put(new JSONObject().put("id",r.getString(0)).put("raw",r.getString(1)).put("received",r.getLong(2)).put("status",r.getString(3)).put("error",r.getString(4)).put("attempts",r.getInt(5)).put("lastAttempt",r.getLong(6)).put("delivered",r.getLong(7)));}return rows;}
 String counts(){try{JSONObject s=stats();return "SMS de 520 detectados: "+s.getInt("detected")+" · Pendientes de entregar: "+s.getInt("pending")+" · Requieren revisión: "+s.getInt("review");}catch(Exception e){return "No se pudieron consultar los contadores.";}}
}
